INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('lesson:ADV-126','lesson','RAM / stabilność','RAM — niestabilność XMP/EXPO i trening pamięci','RAM XMP/EXPO instability and memory training','description: System uruchamia się tylko z profilem JEDEC, zawiesza się po włączeniu XMP/EXPO lub długo trenuje pamięć. symptoms: System uruchamia się tylko z profilem JEDEC, zawiesza się po włączeniu XMP/EXPO lub długo trenuje pamięć. steps: Zidentyfikuj model, rewizję i dokładny objaw: RAM — niestabilność XMP/EXPO i trening pamięci.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Zapisz CPU, płytę, BIOS, moduły, sloty i profil; porównaj z listą QVL oraz specyfikacją kontrolera.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Przywróć ustawienia domyślne i testuj moduły pojedynczo; nie zwiększaj napięć bez dokumentacji.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Potwierdź stabilność w konfiguracji obsługiwanej przez platformę i zapisz parametry. body: System uruchamia się tylko z profilem JEDEC, zawiesza się po włączeniu XMP/EXPO lub długo trenuje pamięć. Zapisz CPU, płytę, BIOS, moduły, sloty i profil; porównaj z listą QVL oraz specyfikacją kontrolera. Przywróć ustawienia domyślne i testuj moduły pojedynczo; nie zwiększaj napięć bez dokumentacji. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Potwierdź stabilność w konfiguracji obsługiwanej przez platformę i zapisz parametry. diagnosis: Zapisz CPU, płytę, BIOS, moduły, sloty i profil; porównaj z listą QVL oraz specyfikacją kontrolera. repair: Przywróć ustawienia domyślne i testuj moduły pojedynczo; nie zwiększaj napięć bez dokumentacji. verify: Potwierdź stabilność w konfiguracji obsługiwanej przez platformę i zapisz parametry. warning: Nie kopiuj profilu napięć z innego zestawu RAM/CPU.','descriptionEn: This lesson investigates memory instability caused by XMP/EXPO profiles and memory training. symptomsEn: This lesson investigates memory instability caused by XMP/EXPO profiles and memory training. stepsEn: Identify the exact model, revision and symptom: RAM XMP/EXPO instability and memory training.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Record CPU, motherboard, BIOS, modules, slots and profile; compare with the QVL and memory-controller specification.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Restore defaults and test modules individually; do not increase voltage without platform documentation.; Repeat the original scenario and check for side effects.; Run the acceptance test: Confirm stability using a configuration supported by the platform and record the final parameters. bodyEn: This lesson investigates memory instability caused by XMP/EXPO profiles and memory training. Record CPU, motherboard, BIOS, modules, slots and profile; compare with the QVL and memory-controller specification. Restore defaults and test modules individually; do not increase voltage without platform documentation. Confirm stability using a configuration supported by the platform and record the final parameters. diagnosisEn: Record CPU, motherboard, BIOS, modules, slots and profile; compare with the QVL and memory-controller specification. repairEn: Restore defaults and test modules individually; do not increase voltage without platform documentation. verifyEn: Confirm stability using a configuration supported by the platform and record the final parameters. warningEn: Do not copy timing or voltage values from a different CPU and memory kit.','RAM,DDR5,XMP,EXPO,memory training',''),
('lesson:ADV-127','lesson','RAM / testy','MemTest — interpretacja błędów pamięci RAM','MemTest interpretation for RAM errors','description: Błędy testu pamięci mogą zależeć od modułu, gniazda, ustawień lub kontrolera. symptoms: Błędy testu pamięci mogą zależeć od modułu, gniazda, ustawień lub kontrolera. steps: Zidentyfikuj model, rewizję i dokładny objaw: MemTest — interpretacja błędów pamięci RAM.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Zapisz numer testu, adres, wzorzec, liczbę błędów, konfigurację i warunki temperatury.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Przywróć ustawienia JEDEC, przetestuj każdy moduł i slot zgodnie z instrukcją płyty.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Powtórz pełny zakres testu po naprawie; pojedynczy przebieg bez błędów nie jest gwarancją. body: Błędy testu pamięci mogą zależeć od modułu, gniazda, ustawień lub kontrolera. Zapisz numer testu, adres, wzorzec, liczbę błędów, konfigurację i warunki temperatury. Przywróć ustawienia JEDEC, przetestuj każdy moduł i slot zgodnie z instrukcją płyty. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Powtórz pełny zakres testu po naprawie; pojedynczy przebieg bez błędów nie jest gwarancją. diagnosis: Zapisz numer testu, adres, wzorzec, liczbę błędów, konfigurację i warunki temperatury. repair: Przywróć ustawienia JEDEC, przetestuj każdy moduł i slot zgodnie z instrukcją płyty. verify: Powtórz pełny zakres testu po naprawie; pojedynczy przebieg bez błędów nie jest gwarancją. warning: Nie wyciągaj modułów przy zasilonym komputerze.','descriptionEn: This lesson teaches how to interpret memory-test errors and isolate a DIMM, slot or platform issue. symptomsEn: This lesson teaches how to interpret memory-test errors and isolate a DIMM, slot or platform issue. stepsEn: Identify the exact model, revision and symptom: MemTest interpretation for RAM errors.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Record test number, address, pattern, error count, installed modules and temperature conditions.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Restore JEDEC defaults and test each module and slot according to the motherboard manual.; Repeat the original scenario and check for side effects.; Run the acceptance test: Repeat the full test plan after repair; one clean pass does not guarantee long-term stability. bodyEn: This lesson teaches how to interpret memory-test errors and isolate a DIMM, slot or platform issue. Record test number, address, pattern, error count, installed modules and temperature conditions. Restore JEDEC defaults and test each module and slot according to the motherboard manual. Repeat the full test plan after repair; one clean pass does not guarantee long-term stability. diagnosisEn: Record test number, address, pattern, error count, installed modules and temperature conditions. repairEn: Restore JEDEC defaults and test each module and slot according to the motherboard manual. verifyEn: Repeat the full test plan after repair; one clean pass does not guarantee long-term stability. warningEn: Never remove or reseat memory while the computer is powered.','MemTest,RAM,DDR,diagnostics',''),
('lesson:ADV-128','lesson','CPU / chłodzenie','CPU — temperatury, limity i thermal throttling','CPU temperatures, limits and thermal throttling','description: Procesor obniża taktowanie lub system wyłącza się przy dużym obciążeniu. symptoms: Procesor obniża taktowanie lub system wyłącza się przy dużym obciążeniu. steps: Zidentyfikuj model, rewizję i dokładny objaw: CPU — temperatury, limity i thermal throttling.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź temperatury, limity termiczne, taktowanie, moc, chłodzenie, ustawienia BIOS i logi.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Usuń potwierdzony problem chłodzenia; nie zwiększaj limitów mocy w celu zamaskowania usterki.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Porównaj krótki test po naprawie przy tych samych warunkach otoczenia. body: Procesor obniża taktowanie lub system wyłącza się przy dużym obciążeniu. Sprawdź temperatury, limity termiczne, taktowanie, moc, chłodzenie, ustawienia BIOS i logi. Usuń potwierdzony problem chłodzenia; nie zwiększaj limitów mocy w celu zamaskowania usterki. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Porównaj krótki test po naprawie przy tych samych warunkach otoczenia. diagnosis: Sprawdź temperatury, limity termiczne, taktowanie, moc, chłodzenie, ustawienia BIOS i logi. repair: Usuń potwierdzony problem chłodzenia; nie zwiększaj limitów mocy w celu zamaskowania usterki. verify: Porównaj krótki test po naprawie przy tych samych warunkach otoczenia. warning: Przerwij przy gwałtownym wzroście temperatury, hałasie, zapachu lub wyłączeniu termicznym.','descriptionEn: This lesson covers CPU temperature, power limits and thermal-throttling analysis. symptomsEn: This lesson covers CPU temperature, power limits and thermal-throttling analysis. stepsEn: Identify the exact model, revision and symptom: CPU temperatures, limits and thermal throttling.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Review temperatures, thermal limits, clock speed, package power, cooling, BIOS settings and logs.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Correct a confirmed cooling issue; do not raise power limits to hide a thermal fault.; Repeat the original scenario and check for side effects.; Run the acceptance test: Compare a short post-repair test under the same ambient and workload conditions. bodyEn: This lesson covers CPU temperature, power limits and thermal-throttling analysis. Review temperatures, thermal limits, clock speed, package power, cooling, BIOS settings and logs. Correct a confirmed cooling issue; do not raise power limits to hide a thermal fault. Compare a short post-repair test under the same ambient and workload conditions. diagnosisEn: Review temperatures, thermal limits, clock speed, package power, cooling, BIOS settings and logs. repairEn: Correct a confirmed cooling issue; do not raise power limits to hide a thermal fault. verifyEn: Compare a short post-repair test under the same ambient and workload conditions. warningEn: Stop for a rapid temperature rise, abnormal noise, odour or thermal shutdown.','CPU,thermal,throttling,temperature,VRM',''),
('lesson:ADV-129','lesson','Chłodzenie / wentylatory','Wentylator 3-pin, 4-pin PWM i sterowanie BIOS','3-pin fan, 4-pin PWM and BIOS fan control','description: Wentylator lub pompa nie startuje, nie raportuje RPM albo pracuje na pełnej prędkości. symptoms: Wentylator lub pompa nie startuje, nie raportuje RPM albo pracuje na pełnej prędkości. steps: Zidentyfikuj model, rewizję i dokładny objaw: Wentylator 3-pin, 4-pin PWM i sterowanie BIOS.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź typ złącza, pinout producenta, wymagane napięcie, sygnał tach i sterowanie PWM.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Ustaw właściwy tryb DC/PWM zgodnie z urządzeniem; nie podawaj napięcia na pin sygnałowy.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Sprawdź start po zimnym uruchomieniu, RPM i reakcję na bezpieczną zmianę krzywej. body: Wentylator lub pompa nie startuje, nie raportuje RPM albo pracuje na pełnej prędkości. Sprawdź typ złącza, pinout producenta, wymagane napięcie, sygnał tach i sterowanie PWM. Ustaw właściwy tryb DC/PWM zgodnie z urządzeniem; nie podawaj napięcia na pin sygnałowy. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Sprawdź start po zimnym uruchomieniu, RPM i reakcję na bezpieczną zmianę krzywej. diagnosis: Sprawdź typ złącza, pinout producenta, wymagane napięcie, sygnał tach i sterowanie PWM. repair: Ustaw właściwy tryb DC/PWM zgodnie z urządzeniem; nie podawaj napięcia na pin sygnałowy. verify: Sprawdź start po zimnym uruchomieniu, RPM i reakcję na bezpieczną zmianę krzywej. warning: Nie podłączaj pompy do niezgodnego headera i nie testuj nieznanego pinoutu.','descriptionEn: This lesson explains 3-pin DC and 4-pin PWM fan control, tachometer feedback and BIOS settings. symptomsEn: This lesson explains 3-pin DC and 4-pin PWM fan control, tachometer feedback and BIOS settings. stepsEn: Identify the exact model, revision and symptom: 3-pin fan, 4-pin PWM and BIOS fan control.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check connector type, OEM pinout, rated voltage, tach signal and PWM control.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Select the correct DC/PWM mode for the device; never apply voltage to a signal pin.; Repeat the original scenario and check for side effects.; Run the acceptance test: Verify cold-start operation, RPM reporting and safe response to a fan curve. bodyEn: This lesson explains 3-pin DC and 4-pin PWM fan control, tachometer feedback and BIOS settings. Check connector type, OEM pinout, rated voltage, tach signal and PWM control. Select the correct DC/PWM mode for the device; never apply voltage to a signal pin. Verify cold-start operation, RPM reporting and safe response to a fan curve. diagnosisEn: Check connector type, OEM pinout, rated voltage, tach signal and PWM control. repairEn: Select the correct DC/PWM mode for the device; never apply voltage to a signal pin. verifyEn: Verify cold-start operation, RPM reporting and safe response to a fan curve. warningEn: Do not connect a pump to an incompatible header or guess an unknown pinout.','fan,3-pin,4-pin,PWM,tachometer,BIOS',''),
('lesson:ADV-130','lesson','GPU / grafika','GPU — artefakty, VRAM i stabilność obrazu','GPU artifacts, VRAM and display stability','description: Artefakty, migotanie, czarny ekran lub awaria sterownika pojawiają się w grach albo już w POST. symptoms: Artefakty, migotanie, czarny ekran lub awaria sterownika pojawiają się w grach albo już w POST. steps: Zidentyfikuj model, rewizję i dokładny objaw: GPU — artefakty, VRAM i stabilność obrazu.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Ustal, czy artefakty występują przed Windows, na innym monitorze i przy ustawieniach fabrycznych.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Wyklucz kabel, monitor, temperaturę i sterownik; test VRAM prowadź kontrolowanie i bez długiego obciążenia nieznanej karty.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Powtórz test obrazu, temperatury i stabilności; sprawdź brak błędów w logach. body: Artefakty, migotanie, czarny ekran lub awaria sterownika pojawiają się w grach albo już w POST. Ustal, czy artefakty występują przed Windows, na innym monitorze i przy ustawieniach fabrycznych. Wyklucz kabel, monitor, temperaturę i sterownik; test VRAM prowadź kontrolowanie i bez długiego obciążenia nieznanej karty. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Powtórz test obrazu, temperatury i stabilności; sprawdź brak błędów w logach. diagnosis: Ustal, czy artefakty występują przed Windows, na innym monitorze i przy ustawieniach fabrycznych. repair: Wyklucz kabel, monitor, temperaturę i sterownik; test VRAM prowadź kontrolowanie i bez długiego obciążenia nieznanej karty. verify: Powtórz test obrazu, temperatury i stabilności; sprawdź brak błędów w logach. warning: Nie podkręcaj GPU w trakcie diagnozy i przerwij przy zapachu lub nadmiernej temperaturze.','descriptionEn: This lesson separates GPU artefacts caused by the display path, driver, temperature, VRAM or graphics hardware. symptomsEn: This lesson separates GPU artefacts caused by the display path, driver, temperature, VRAM or graphics hardware. stepsEn: Identify the exact model, revision and symptom: GPU artifacts, VRAM and display stability.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check whether artefacts appear before Windows, with another monitor and at factory settings.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Rule out cable, monitor, temperature and driver; run VRAM tests only in a controlled way and avoid long stress tests on an unknown card.; Repeat the original scenario and check for side effects.; Run the acceptance test: Repeat display, temperature and stability checks; review logs for new errors. bodyEn: This lesson separates GPU artefacts caused by the display path, driver, temperature, VRAM or graphics hardware. Check whether artefacts appear before Windows, with another monitor and at factory settings. Rule out cable, monitor, temperature and driver; run VRAM tests only in a controlled way and avoid long stress tests on an unknown card. Repeat display, temperature and stability checks; review logs for new errors. diagnosisEn: Check whether artefacts appear before Windows, with another monitor and at factory settings. repairEn: Rule out cable, monitor, temperature and driver; run VRAM tests only in a controlled way and avoid long stress tests on an unknown card. verifyEn: Repeat display, temperature and stability checks; review logs for new errors. warningEn: Do not overclock during diagnosis; stop for unusual heat, smell or electrical noise.','GPU,VRAM,artifacts,display,diagnostics',''),
('lesson:ADV-131','lesson','GPU / sterowniki','GPU — czysta instalacja sterownika i profil systemu','GPU clean driver installation and system profile','description: Ekran miga, aplikacje nie wykorzystują właściwej karty lub pojawiają się błędy sterownika. symptoms: Ekran miga, aplikacje nie wykorzystują właściwej karty lub pojawiają się błędy sterownika. steps: Zidentyfikuj model, rewizję i dokładny objaw: GPU — czysta instalacja sterownika i profil systemu.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Zapisz GPU, wersję Windows, wersję sterownika i aktualizacje; sprawdź, czy problem występuje w trybie awaryjnym.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Użyj oficjalnego instalatora producenta; narzędzie czyszczenia stosuj tylko według zaleceń i po punkcie przywracania.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Przetestuj pulpit, multimedia, wyjścia obrazu i umiarkowane obciążenie. body: Ekran miga, aplikacje nie wykorzystują właściwej karty lub pojawiają się błędy sterownika. Zapisz GPU, wersję Windows, wersję sterownika i aktualizacje; sprawdź, czy problem występuje w trybie awaryjnym. Użyj oficjalnego instalatora producenta; narzędzie czyszczenia stosuj tylko według zaleceń i po punkcie przywracania. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Przetestuj pulpit, multimedia, wyjścia obrazu i umiarkowane obciążenie. diagnosis: Zapisz GPU, wersję Windows, wersję sterownika i aktualizacje; sprawdź, czy problem występuje w trybie awaryjnym. repair: Użyj oficjalnego instalatora producenta; narzędzie czyszczenia stosuj tylko według zaleceń i po punkcie przywracania. verify: Przetestuj pulpit, multimedia, wyjścia obrazu i umiarkowane obciążenie. warning: Nie instaluj sterowników z nieoficjalnych serwisów i nie kasuj sterowników chipsetu przy okazji.','descriptionEn: This lesson covers a controlled graphics-driver reinstall and verification of the active GPU profile. symptomsEn: This lesson covers a controlled graphics-driver reinstall and verification of the active GPU profile. stepsEn: Identify the exact model, revision and symptom: GPU clean driver installation and system profile.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Record GPU model, Windows build, driver version and recent updates; compare behaviour in Safe Mode if relevant.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Use the official vendor installer; use cleanup tools only when recommended and after a restore point or backup.; Repeat the original scenario and check for side effects.; Run the acceptance test: Test desktop, media playback, display outputs and a moderate workload. bodyEn: This lesson covers a controlled graphics-driver reinstall and verification of the active GPU profile. Record GPU model, Windows build, driver version and recent updates; compare behaviour in Safe Mode if relevant. Use the official vendor installer; use cleanup tools only when recommended and after a restore point or backup. Test desktop, media playback, display outputs and a moderate workload. diagnosisEn: Record GPU model, Windows build, driver version and recent updates; compare behaviour in Safe Mode if relevant. repairEn: Use the official vendor installer; use cleanup tools only when recommended and after a restore point or backup. verifyEn: Test desktop, media playback, display outputs and a moderate workload. warningEn: Do not install graphics drivers from unofficial download aggregators or remove chipset drivers incidentally.','GPU,NVIDIA,AMD,driver,Windows',''),
('lesson:ADV-132','lesson','Płyta główna / POST','POST — kody LED, sygnały dźwiękowe i minimalna konfiguracja','POST codes, diagnostic LEDs, beeps and minimal configuration','description: Komputer zatrzymuje się na CPU/DRAM/VGA/BOOT, wydaje sygnały dźwiękowe lub nie pokazuje obrazu. symptoms: Komputer zatrzymuje się na CPU/DRAM/VGA/BOOT, wydaje sygnały dźwiękowe lub nie pokazuje obrazu. steps: Zidentyfikuj model, rewizję i dokładny objaw: POST — kody LED, sygnały dźwiękowe i minimalna konfiguracja.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Zapisz dokładny kod, czas świecenia i instrukcję modelu; sprawdź kompatybilność CPU/RAM i zasilanie.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Zbuduj minimalną konfigurację według manuala i zmieniaj jeden element na raz.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Przywróć pełną konfigurację etapami i sprawdź kilka startów. body: Komputer zatrzymuje się na CPU/DRAM/VGA/BOOT, wydaje sygnały dźwiękowe lub nie pokazuje obrazu. Zapisz dokładny kod, czas świecenia i instrukcję modelu; sprawdź kompatybilność CPU/RAM i zasilanie. Zbuduj minimalną konfigurację według manuala i zmieniaj jeden element na raz. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Przywróć pełną konfigurację etapami i sprawdź kilka startów. diagnosis: Zapisz dokładny kod, czas świecenia i instrukcję modelu; sprawdź kompatybilność CPU/RAM i zasilanie. repair: Zbuduj minimalną konfigurację według manuala i zmieniaj jeden element na raz. verify: Przywróć pełną konfigurację etapami i sprawdź kilka startów. warning: Nie mostkuj styków i nie przekładaj RAM przy podłączonym zasilaniu.','descriptionEn: This lesson uses POST LEDs, beep codes and minimal hardware configuration to isolate startup failures. symptomsEn: This lesson uses POST LEDs, beep codes and minimal hardware configuration to isolate startup failures. stepsEn: Identify the exact model, revision and symptom: POST codes, diagnostic LEDs, beeps and minimal configuration.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Record the exact code, timing and motherboard manual; check CPU/RAM compatibility and required power connectors.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Build a minimum configuration according to the board manual and change one component at a time.; Repeat the original scenario and check for side effects.; Run the acceptance test: Restore the full configuration in stages and complete several successful starts. bodyEn: This lesson uses POST LEDs, beep codes and minimal hardware configuration to isolate startup failures. Record the exact code, timing and motherboard manual; check CPU/RAM compatibility and required power connectors. Build a minimum configuration according to the board manual and change one component at a time. Restore the full configuration in stages and complete several successful starts. diagnosisEn: Record the exact code, timing and motherboard manual; check CPU/RAM compatibility and required power connectors. repairEn: Build a minimum configuration according to the board manual and change one component at a time. verifyEn: Restore the full configuration in stages and complete several successful starts. warningEn: Do not bridge contacts or reseat memory while power is connected.','POST,beep,debug LED,RAM,CPU,BIOS',''),
('lesson:ADV-133','lesson','BIOS / RTC','Reset CMOS i wymiana baterii RTC','CMOS reset and RTC battery replacement','description: Ustawienia BIOS resetują się, data/godzina są nieprawidłowe lub pojawia się komunikat CMOS. symptoms: Ustawienia BIOS resetują się, data/godzina są nieprawidłowe lub pojawia się komunikat CMOS. steps: Zidentyfikuj model, rewizję i dokładny objaw: Reset CMOS i wymiana baterii RTC.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź baterię i złącze według specyfikacji modelu; odróżnij RTC od pamięci firmware SPI.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Reset wykonaj wyłącznie metodą przewidzianą przez płytę; zapisz ustawienia i klucz BitLocker przed zmianą UEFI.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Sprawdź czas, ustawienia bootowania, wykrycie urządzeń i brak ponownego resetu. body: Ustawienia BIOS resetują się, data/godzina są nieprawidłowe lub pojawia się komunikat CMOS. Sprawdź baterię i złącze według specyfikacji modelu; odróżnij RTC od pamięci firmware SPI. Reset wykonaj wyłącznie metodą przewidzianą przez płytę; zapisz ustawienia i klucz BitLocker przed zmianą UEFI. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Sprawdź czas, ustawienia bootowania, wykrycie urządzeń i brak ponownego resetu. diagnosis: Sprawdź baterię i złącze według specyfikacji modelu; odróżnij RTC od pamięci firmware SPI. repair: Reset wykonaj wyłącznie metodą przewidzianą przez płytę; zapisz ustawienia i klucz BitLocker przed zmianą UEFI. verify: Sprawdź czas, ustawienia bootowania, wykrycie urządzeń i brak ponownego resetu. warning: Nie zwieraj nieoznaczonych padów i nie zakładaj, że każda platforma używa CR2032.','descriptionEn: This lesson distinguishes RTC battery, CMOS settings and SPI firmware storage. symptomsEn: This lesson distinguishes RTC battery, CMOS settings and SPI firmware storage. stepsEn: Identify the exact model, revision and symptom: CMOS reset and RTC battery replacement.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check the battery and connector against the exact model specification; distinguish the RTC supply from SPI firmware.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Reset settings only using the board-supported procedure; record configuration and secure BitLocker recovery access first.; Repeat the original scenario and check for side effects.; Run the acceptance test: Verify time, boot settings, device detection and that settings remain saved after shutdown. bodyEn: This lesson distinguishes RTC battery, CMOS settings and SPI firmware storage. Check the battery and connector against the exact model specification; distinguish the RTC supply from SPI firmware. Reset settings only using the board-supported procedure; record configuration and secure BitLocker recovery access first. Verify time, boot settings, device detection and that settings remain saved after shutdown. diagnosisEn: Check the battery and connector against the exact model specification; distinguish the RTC supply from SPI firmware. repairEn: Reset settings only using the board-supported procedure; record configuration and secure BitLocker recovery access first. verifyEn: Verify time, boot settings, device detection and that settings remain saved after shutdown. warningEn: Do not short unidentified pads or assume every platform uses a CR2032 cell.','CMOS,RTC,CR2032,BIOS,date time',''),
('lesson:ADV-134','lesson','UEFI / bezpieczeństwo','Secure Boot — certyfikaty, TPM i zgodność rozruchu','Secure Boot certificates, TPM and boot compatibility','description: Błąd rozruchu po zmianie Secure Boot, firmware, TPM lub aktualizacji platformy. symptoms: Błąd rozruchu po zmianie Secure Boot, firmware, TPM lub aktualizacji platformy. steps: Zidentyfikuj model, rewizję i dokładny objaw: Secure Boot — certyfikaty, TPM i zgodność rozruchu.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Zapisz stan Secure Boot, TPM, tryb UEFI, komunikaty i klucz BitLocker; sprawdź dokumentację OEM.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Wdrażaj aktualizację certyfikatów i konfiguracji tylko zgodnie z komunikatem Microsoft/OEM i etapowaniem producenta.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Sprawdź rozruch, stan TPM, zdarzenia Secure Boot i ochronę BitLocker po restarcie. body: Błąd rozruchu po zmianie Secure Boot, firmware, TPM lub aktualizacji platformy. Zapisz stan Secure Boot, TPM, tryb UEFI, komunikaty i klucz BitLocker; sprawdź dokumentację OEM. Wdrażaj aktualizację certyfikatów i konfiguracji tylko zgodnie z komunikatem Microsoft/OEM i etapowaniem producenta. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Sprawdź rozruch, stan TPM, zdarzenia Secure Boot i ochronę BitLocker po restarcie. diagnosis: Zapisz stan Secure Boot, TPM, tryb UEFI, komunikaty i klucz BitLocker; sprawdź dokumentację OEM. repair: Wdrażaj aktualizację certyfikatów i konfiguracji tylko zgodnie z komunikatem Microsoft/OEM i etapowaniem producenta. verify: Sprawdź rozruch, stan TPM, zdarzenia Secure Boot i ochronę BitLocker po restarcie. warning: Nie kasuj kluczy TPM ani nie resetuj Secure Boot bez autoryzacji i planu odzyskiwania.','descriptionEn: This lesson explains Secure Boot, TPM state and how platform changes can affect encrypted startup. symptomsEn: This lesson explains Secure Boot, TPM state and how platform changes can affect encrypted startup. stepsEn: Identify the exact model, revision and symptom: Secure Boot certificates, TPM and boot compatibility.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Record Secure Boot, TPM and UEFI state, messages and recovery arrangements; consult the OEM documentation.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Apply certificate or platform changes only according to Microsoft/OEM instructions and the vendor rollout plan.; Repeat the original scenario and check for side effects.; Run the acceptance test: Verify boot, TPM state, Secure Boot events and BitLocker protection after restart. bodyEn: This lesson explains Secure Boot, TPM state and how platform changes can affect encrypted startup. Record Secure Boot, TPM and UEFI state, messages and recovery arrangements; consult the OEM documentation. Apply certificate or platform changes only according to Microsoft/OEM instructions and the vendor rollout plan. Verify boot, TPM state, Secure Boot events and BitLocker protection after restart. diagnosisEn: Record Secure Boot, TPM and UEFI state, messages and recovery arrangements; consult the OEM documentation. repairEn: Apply certificate or platform changes only according to Microsoft/OEM instructions and the vendor rollout plan. verifyEn: Verify boot, TPM state, Secure Boot events and BitLocker protection after restart. warningEn: Do not clear TPM keys or reset Secure Boot without authorization and a recovery plan.','Secure Boot,TPM,UEFI,BitLocker,certificates',''),
('lesson:ADV-135','lesson','BIOS / firmware','Aktualizacja BIOS/UEFI — kontrola zgodności i ryzyka','BIOS/UEFI update compatibility and risk control','description: Należy poprawić kompatybilność, błąd firmware lub obsługę sprzętu. symptoms: Należy poprawić kompatybilność, błąd firmware lub obsługę sprzętu. steps: Zidentyfikuj model, rewizję i dokładny objaw: Aktualizacja BIOS/UEFI — kontrola zgodności i ryzyka.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Zweryfikuj dokładny model, rewizję, wersję pliku, wymagania pośrednie, sumę kontrolną i historię aktualizacji.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Aktualizuj metodą OEM, przy stabilnym zasilaniu; nie używaj pliku podobnego modelu ani nie przerywaj procesu.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Po aktualizacji sprawdź wersję, ustawienia, Secure Boot, TPM, BitLocker i urządzenia. body: Należy poprawić kompatybilność, błąd firmware lub obsługę sprzętu. Zweryfikuj dokładny model, rewizję, wersję pliku, wymagania pośrednie, sumę kontrolną i historię aktualizacji. Aktualizuj metodą OEM, przy stabilnym zasilaniu; nie używaj pliku podobnego modelu ani nie przerywaj procesu. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Po aktualizacji sprawdź wersję, ustawienia, Secure Boot, TPM, BitLocker i urządzenia. diagnosis: Zweryfikuj dokładny model, rewizję, wersję pliku, wymagania pośrednie, sumę kontrolną i historię aktualizacji. repair: Aktualizuj metodą OEM, przy stabilnym zasilaniu; nie używaj pliku podobnego modelu ani nie przerywaj procesu. verify: Po aktualizacji sprawdź wersję, ustawienia, Secure Boot, TPM, BitLocker i urządzenia. warning: Nie aktualizuj BIOS tylko dlatego, że dostępna jest nowsza wersja; sprawdź release notes i ryzyko.','descriptionEn: This lesson covers BIOS/UEFI update eligibility, firmware compatibility and recovery risks. symptomsEn: This lesson covers BIOS/UEFI update eligibility, firmware compatibility and recovery risks. stepsEn: Identify the exact model, revision and symptom: BIOS/UEFI update compatibility and risk control.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Verify exact model, board revision, file version, prerequisite updates, checksum and release notes.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Use the OEM update method with stable power; never use a file for a similar model or interrupt flashing.; Repeat the original scenario and check for side effects.; Run the acceptance test: After updating, check firmware version, settings, Secure Boot, TPM, BitLocker and device detection. bodyEn: This lesson covers BIOS/UEFI update eligibility, firmware compatibility and recovery risks. Verify exact model, board revision, file version, prerequisite updates, checksum and release notes. Use the OEM update method with stable power; never use a file for a similar model or interrupt flashing. After updating, check firmware version, settings, Secure Boot, TPM, BitLocker and device detection. diagnosisEn: Verify exact model, board revision, file version, prerequisite updates, checksum and release notes. repairEn: Use the OEM update method with stable power; never use a file for a similar model or interrupt flashing. verifyEn: After updating, check firmware version, settings, Secure Boot, TPM, BitLocker and device detection. warningEn: Do not flash BIOS solely because a newer version exists; evaluate release notes and service risk.','BIOS,UEFI,firmware,update,OEM',''),
('lesson:ADV-136','lesson','Porty / USB','Port USB-A/USB-C — brak danych i uszkodzone złącze','USB-A/USB-C port no-data and connector damage','description: Port ładuje, ale nie przesyła danych, rozłącza urządzenia lub jest mechanicznie luźny. symptoms: Port ładuje, ale nie przesyła danych, rozłącza urządzenia lub jest mechanicznie luźny. steps: Zidentyfikuj model, rewizję i dokładny objaw: Port USB-A/USB-C — brak danych i uszkodzone złącze.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Porównaj urządzenie, kabel, drugi port, Menedżer urządzeń i logi; obejrzyj port po odłączeniu zasilania.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Naprawa mechaniczna wymaga właściwej dokumentacji i oceny padów; nie czyść portu metalową igłą.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Sprawdź transfer, stabilność i brak nagrzewania przy kilku kontrolowanych podłączeniach. body: Port ładuje, ale nie przesyła danych, rozłącza urządzenia lub jest mechanicznie luźny. Porównaj urządzenie, kabel, drugi port, Menedżer urządzeń i logi; obejrzyj port po odłączeniu zasilania. Naprawa mechaniczna wymaga właściwej dokumentacji i oceny padów; nie czyść portu metalową igłą. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Sprawdź transfer, stabilność i brak nagrzewania przy kilku kontrolowanych podłączeniach. diagnosis: Porównaj urządzenie, kabel, drugi port, Menedżer urządzeń i logi; obejrzyj port po odłączeniu zasilania. repair: Naprawa mechaniczna wymaga właściwej dokumentacji i oceny padów; nie czyść portu metalową igłą. verify: Sprawdź transfer, stabilność i brak nagrzewania przy kilku kontrolowanych podłączeniach. warning: Nie wciskaj wtyku w luźny port i nie wykonuj pomiarów wewnątrz zasilonego złącza.','descriptionEn: This lesson diagnoses USB-A/USB-C ports that provide power but fail data transfer or have mechanical damage. symptomsEn: This lesson diagnoses USB-A/USB-C ports that provide power but fail data transfer or have mechanical damage. stepsEn: Identify the exact model, revision and symptom: USB-A/USB-C port no-data and connector damage.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Compare peripheral, cable and another port; review Device Manager and logs, then inspect the connector with power isolated.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Mechanical repair requires matching board documentation and pad inspection; never probe a live port with a metal needle.; Repeat the original scenario and check for side effects.; Run the acceptance test: Verify transfer, connection stability and absence of abnormal heating over several controlled connections. bodyEn: This lesson diagnoses USB-A/USB-C ports that provide power but fail data transfer or have mechanical damage. Compare peripheral, cable and another port; review Device Manager and logs, then inspect the connector with power isolated. Mechanical repair requires matching board documentation and pad inspection; never probe a live port with a metal needle. Verify transfer, connection stability and absence of abnormal heating over several controlled connections. diagnosisEn: Compare peripheral, cable and another port; review Device Manager and logs, then inspect the connector with power isolated. repairEn: Mechanical repair requires matching board documentation and pad inspection; never probe a live port with a metal needle. verifyEn: Verify transfer, connection stability and absence of abnormal heating over several controlled connections. warningEn: Do not force a plug into a loose connector or probe inside a powered port.','USB,port,connector,ESD,data',''),
('lesson:ADV-137','lesson','Sieć / Wi-Fi','Wi-Fi — anteny, przewody i diagnostyka sygnału','Wi-Fi antennas, coax leads and signal diagnostics','description: Zasięg jest słaby, łącze rozłącza się po poruszeniu klapą lub karta nie wykrywa sieci. symptoms: Zasięg jest słaby, łącze rozłącza się po poruszeniu klapą lub karta nie wykrywa sieci. steps: Zidentyfikuj model, rewizję i dokładny objaw: Wi-Fi — anteny, przewody i diagnostyka sygnału.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź drugi router i urządzenie, pasmo, kanał, sterownik i stan przewodów antenowych.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Otwieraj obudowę zgodnie z instrukcją; przewody antenowe zatrzaskuj odpowiednim narzędziem i w prawidłowe gniazdo MAIN/AUX.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Wykonaj test na 2,4/5/6 GHz, porównaj RSSI i stabilność po kilku cyklach uśpienia. body: Zasięg jest słaby, łącze rozłącza się po poruszeniu klapą lub karta nie wykrywa sieci. Sprawdź drugi router i urządzenie, pasmo, kanał, sterownik i stan przewodów antenowych. Otwieraj obudowę zgodnie z instrukcją; przewody antenowe zatrzaskuj odpowiednim narzędziem i w prawidłowe gniazdo MAIN/AUX. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Wykonaj test na 2,4/5/6 GHz, porównaj RSSI i stabilność po kilku cyklach uśpienia. diagnosis: Sprawdź drugi router i urządzenie, pasmo, kanał, sterownik i stan przewodów antenowych. repair: Otwieraj obudowę zgodnie z instrukcją; przewody antenowe zatrzaskuj odpowiednim narzędziem i w prawidłowe gniazdo MAIN/AUX. verify: Wykonaj test na 2,4/5/6 GHz, porównaj RSSI i stabilność po kilku cyklach uśpienia. warning: Nie ciągnij przewodów koncentrycznych za kabel i nie używaj niezgodnej anteny.','descriptionEn: This lesson covers laptop Wi-Fi antenna leads, coax connectors and signal-quality troubleshooting. symptomsEn: This lesson covers laptop Wi-Fi antenna leads, coax connectors and signal-quality troubleshooting. stepsEn: Identify the exact model, revision and symptom: Wi-Fi antennas, coax leads and signal diagnostics.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Compare another router/device, band, channel and driver; inspect antenna coax routing and connectors.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Open the case using the model-specific guide; seat MAIN/AUX antenna plugs with the correct tool and orientation.; Repeat the original scenario and check for side effects.; Run the acceptance test: Test 2.4/5/6 GHz where supported, compare RSSI and check stability after sleep cycles. bodyEn: This lesson covers laptop Wi-Fi antenna leads, coax connectors and signal-quality troubleshooting. Compare another router/device, band, channel and driver; inspect antenna coax routing and connectors. Open the case using the model-specific guide; seat MAIN/AUX antenna plugs with the correct tool and orientation. Test 2.4/5/6 GHz where supported, compare RSSI and check stability after sleep cycles. diagnosisEn: Compare another router/device, band, channel and driver; inspect antenna coax routing and connectors. repairEn: Open the case using the model-specific guide; seat MAIN/AUX antenna plugs with the correct tool and orientation. verifyEn: Test 2.4/5/6 GHz where supported, compare RSSI and check stability after sleep cycles. warningEn: Do not pull coax leads by the cable or use an incompatible antenna.','Wi-Fi,antenna,coax,signal,wireless',''),
('lesson:ADV-138','lesson','Sieć / diagnostyka','DNS i DHCP — rozdzielenie problemu lokalnego od operatora','DNS and DHCP troubleshooting: device, router or ISP','description: Urządzenie łączy się z Wi-Fi, ale nie otwiera stron lub otrzymuje adres 169.254.x.x. symptoms: Urządzenie łączy się z Wi-Fi, ale nie otwiera stron lub otrzymuje adres 169.254.x.x. steps: Zidentyfikuj model, rewizję i dokładny objaw: DNS i DHCP — rozdzielenie problemu lokalnego od operatora.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Zapisz ipconfig /all, bramę, DNS, dzierżawę DHCP, wynik ping do bramy i nslookup.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Zmieniaj jedną konfigurację, nie resetuj routera bez kopii; potwierdź usługę operatora.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Sprawdź rozwiązywanie nazw, ping do bramy, dostęp do kilku domen i drugie urządzenie. body: Urządzenie łączy się z Wi-Fi, ale nie otwiera stron lub otrzymuje adres 169.254.x.x. Zapisz ipconfig /all, bramę, DNS, dzierżawę DHCP, wynik ping do bramy i nslookup. Zmieniaj jedną konfigurację, nie resetuj routera bez kopii; potwierdź usługę operatora. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Sprawdź rozwiązywanie nazw, ping do bramy, dostęp do kilku domen i drugie urządzenie. diagnosis: Zapisz ipconfig /all, bramę, DNS, dzierżawę DHCP, wynik ping do bramy i nslookup. repair: Zmieniaj jedną konfigurację, nie resetuj routera bez kopii; potwierdź usługę operatora. verify: Sprawdź rozwiązywanie nazw, ping do bramy, dostęp do kilku domen i drugie urządzenie. warning: Nie publikuj adresów i haseł sieciowych; testuj wyłącznie sieci, do których masz uprawnienia.','descriptionEn: This lesson separates local DHCP, gateway and DNS faults from router or ISP issues. symptomsEn: This lesson separates local DHCP, gateway and DNS faults from router or ISP issues. stepsEn: Identify the exact model, revision and symptom: DNS and DHCP troubleshooting: device, router or ISP.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Record ipconfig /all, gateway, DNS, DHCP lease, gateway ping and nslookup results.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Change one setting at a time; do not factory-reset the router without a configuration backup. Confirm ISP status.; Repeat the original scenario and check for side effects.; Run the acceptance test: Test name resolution, gateway reachability, several domains and a second device. bodyEn: This lesson separates local DHCP, gateway and DNS faults from router or ISP issues. Record ipconfig /all, gateway, DNS, DHCP lease, gateway ping and nslookup results. Change one setting at a time; do not factory-reset the router without a configuration backup. Confirm ISP status. Test name resolution, gateway reachability, several domains and a second device. diagnosisEn: Record ipconfig /all, gateway, DNS, DHCP lease, gateway ping and nslookup results. repairEn: Change one setting at a time; do not factory-reset the router without a configuration backup. Confirm ISP status. verifyEn: Test name resolution, gateway reachability, several domains and a second device. warningEn: Do not publish network passwords, public IP details or private customer network information.','DNS,DHCP,ipconfig,router,network',''),
('lesson:ADV-139','lesson','Sieć / Ethernet','Ethernet — brak linku, autonegocjacja i kabel','Ethernet no-link, autonegotiation and cable diagnosis','description: Brak diody link, prędkość spada do 100 Mb/s lub połączenie zanika. symptoms: Brak diody link, prędkość spada do 100 Mb/s lub połączenie zanika. steps: Zidentyfikuj model, rewizję i dokładny objaw: Ethernet — brak linku, autonegocjacja i kabel.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź kabel, port switcha/routera, adapter, sterownik i ustawienia prędkości bez wymuszania dupleksu.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Użyj testera okablowania dla przewodu i znanego sprawnego portu; aktualizuj sterownik OEM.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Zweryfikuj link speed, utratę pakietów i stabilność przesyłu w obu kierunkach. body: Brak diody link, prędkość spada do 100 Mb/s lub połączenie zanika. Sprawdź kabel, port switcha/routera, adapter, sterownik i ustawienia prędkości bez wymuszania dupleksu. Użyj testera okablowania dla przewodu i znanego sprawnego portu; aktualizuj sterownik OEM. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Zweryfikuj link speed, utratę pakietów i stabilność przesyłu w obu kierunkach. diagnosis: Sprawdź kabel, port switcha/routera, adapter, sterownik i ustawienia prędkości bez wymuszania dupleksu. repair: Użyj testera okablowania dla przewodu i znanego sprawnego portu; aktualizuj sterownik OEM. verify: Zweryfikuj link speed, utratę pakietów i stabilność przesyłu w obu kierunkach. warning: Nie podłączaj przewodu do obwodu PoE, jeśli nie znasz standardu i parametrów.','descriptionEn: This lesson diagnoses Ethernet link negotiation, cable defects and unstable wired connections. symptomsEn: This lesson diagnoses Ethernet link negotiation, cable defects and unstable wired connections. stepsEn: Identify the exact model, revision and symptom: Ethernet no-link, autonegotiation and cable diagnosis.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check cable, switch/router port, adapter, driver and speed settings without forcing duplex unnecessarily.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Use a cable tester and known-good switch port; update the OEM adapter driver if evidence supports it.; Repeat the original scenario and check for side effects.; Run the acceptance test: Verify link speed, packet loss and stable transfer in both directions. bodyEn: This lesson diagnoses Ethernet link negotiation, cable defects and unstable wired connections. Check cable, switch/router port, adapter, driver and speed settings without forcing duplex unnecessarily. Use a cable tester and known-good switch port; update the OEM adapter driver if evidence supports it. Verify link speed, packet loss and stable transfer in both directions. diagnosisEn: Check cable, switch/router port, adapter, driver and speed settings without forcing duplex unnecessarily. repairEn: Use a cable tester and known-good switch port; update the OEM adapter driver if evidence supports it. verifyEn: Verify link speed, packet loss and stable transfer in both directions. warningEn: Do not connect a cable to an unknown PoE source or wiring circuit.','Ethernet,LAN,link,speed,duplex,cable',''),
('lesson:ADV-140','lesson','Obraz / monitor','Monitor — brak obrazu, EDID i tor sygnałowy','Monitor no image, EDID and video signal path','description: Monitor jest wykrywany nieprawidłowo, wyświetla „no signal” lub proponuje złą rozdzielczość. symptoms: Monitor jest wykrywany nieprawidłowo, wyświetla „no signal” lub proponuje złą rozdzielczość. steps: Zidentyfikuj model, rewizję i dokładny objaw: Monitor — brak obrazu, EDID i tor sygnałowy.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź OSD, wejście, kabel, źródło obrazu, EDID i drugi monitor.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Użyj krótkiego, zgodnego przewodu i sprawdź ustawienia GPU; nie wymuszaj trybu spoza specyfikacji.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Przetestuj natywną rozdzielczość, odświeżanie, HDR i uśpienie/wybudzenie. body: Monitor jest wykrywany nieprawidłowo, wyświetla „no signal” lub proponuje złą rozdzielczość. Sprawdź OSD, wejście, kabel, źródło obrazu, EDID i drugi monitor. Użyj krótkiego, zgodnego przewodu i sprawdź ustawienia GPU; nie wymuszaj trybu spoza specyfikacji. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Przetestuj natywną rozdzielczość, odświeżanie, HDR i uśpienie/wybudzenie. diagnosis: Sprawdź OSD, wejście, kabel, źródło obrazu, EDID i drugi monitor. repair: Użyj krótkiego, zgodnego przewodu i sprawdź ustawienia GPU; nie wymuszaj trybu spoza specyfikacji. verify: Przetestuj natywną rozdzielczość, odświeżanie, HDR i uśpienie/wybudzenie. warning: Nie rozbieraj zasilacza monitora; obwody mogą zachować niebezpieczny ładunek.','descriptionEn: This lesson isolates a monitor no-signal issue across OSD settings, cable, EDID and GPU output. symptomsEn: This lesson isolates a monitor no-signal issue across OSD settings, cable, EDID and GPU output. stepsEn: Identify the exact model, revision and symptom: Monitor no image, EDID and video signal path.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check OSD, selected input, cable, source device, EDID and a second monitor.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Use a short compatible cable and supported GPU mode; never force a mode outside the display specification.; Repeat the original scenario and check for side effects.; Run the acceptance test: Test native resolution, refresh rate, HDR where supported and sleep/wake. bodyEn: This lesson isolates a monitor no-signal issue across OSD settings, cable, EDID and GPU output. Check OSD, selected input, cable, source device, EDID and a second monitor. Use a short compatible cable and supported GPU mode; never force a mode outside the display specification. Test native resolution, refresh rate, HDR where supported and sleep/wake. diagnosisEn: Check OSD, selected input, cable, source device, EDID and a second monitor. repairEn: Use a short compatible cable and supported GPU mode; never force a mode outside the display specification. verifyEn: Test native resolution, refresh rate, HDR where supported and sleep/wake. warningEn: Do not open the monitor power supply; internal capacitors may retain hazardous charge.','monitor,EDID,HDMI,DisplayPort,refresh',''),
('lesson:ADV-141','lesson','Laptop / ekran','Matryca eDP — obraz migocze przy poruszaniu klapą','eDP display cable intermittent image when moving lid','description: Obraz zanika lub miga przy zmianie kąta klapy, pojawiają się pasy albo brak podświetlenia. symptoms: Obraz zanika lub miga przy zmianie kąta klapy, pojawiają się pasy albo brak podświetlenia. steps: Zidentyfikuj model, rewizję i dokładny objaw: Matryca eDP — obraz migocze przy poruszaniu klapą.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Porównaj ekran zewnętrzny, ustawienia jasności, latarkę i objaw przy różnych kątach; sprawdź zawiasy.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Otwieraj obudowę i odłącz eDP tylko po odłączeniu zasilania oraz baterii, zgodnie z instrukcją.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Wykonaj test pełnego zakresu kąta i sprawdź brak naprężeń przewodu. body: Obraz zanika lub miga przy zmianie kąta klapy, pojawiają się pasy albo brak podświetlenia. Porównaj ekran zewnętrzny, ustawienia jasności, latarkę i objaw przy różnych kątach; sprawdź zawiasy. Otwieraj obudowę i odłącz eDP tylko po odłączeniu zasilania oraz baterii, zgodnie z instrukcją. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Wykonaj test pełnego zakresu kąta i sprawdź brak naprężeń przewodu. diagnosis: Porównaj ekran zewnętrzny, ustawienia jasności, latarkę i objaw przy różnych kątach; sprawdź zawiasy. repair: Otwieraj obudowę i odłącz eDP tylko po odłączeniu zasilania oraz baterii, zgodnie z instrukcją. verify: Wykonaj test pełnego zakresu kąta i sprawdź brak naprężeń przewodu. warning: Nie podłączaj ani nie odłączaj eDP przy zasilonej płycie.','descriptionEn: This lesson diagnoses intermittent eDP image faults associated with lid movement, hinges or cable routing. symptomsEn: This lesson diagnoses intermittent eDP image faults associated with lid movement, hinges or cable routing. stepsEn: Identify the exact model, revision and symptom: eDP display cable intermittent image when moving lid.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Compare external display, brightness settings, flashlight test and behaviour at different lid angles; inspect hinge movement.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Disconnect the eDP cable only after power and battery isolation, following the exact service manual.; Repeat the original scenario and check for side effects.; Run the acceptance test: Test the full lid-angle range and confirm the cable is not pinched or stretched. bodyEn: This lesson diagnoses intermittent eDP image faults associated with lid movement, hinges or cable routing. Compare external display, brightness settings, flashlight test and behaviour at different lid angles; inspect hinge movement. Disconnect the eDP cable only after power and battery isolation, following the exact service manual. Test the full lid-angle range and confirm the cable is not pinched or stretched. diagnosisEn: Compare external display, brightness settings, flashlight test and behaviour at different lid angles; inspect hinge movement. repairEn: Disconnect the eDP cable only after power and battery isolation, following the exact service manual. verifyEn: Test the full lid-angle range and confirm the cable is not pinched or stretched. warningEn: Never connect or disconnect eDP while the board is powered.','eDP,display,cable,hinge,backlight',''),
('lesson:ADV-142','lesson','Laptop / klawiatura','Klawiatura laptopa — matryca, taśma i zalanie','Laptop keyboard matrix, ribbon cable and spill diagnosis','description: Nie działają wybrane klawisze, cały rząd lub klawiatura nie jest wykrywana. symptoms: Nie działają wybrane klawisze, cały rząd lub klawiatura nie jest wykrywana. steps: Zidentyfikuj model, rewizję i dokładny objaw: Klawiatura laptopa — matryca, taśma i zalanie.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź układ klawiszy, test poza systemem, blokadę Fn, taśmę i historię zalania.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Wymień klawiaturę/taśmę zgodnie z numerem części; przy śladach cieczy przerwij zasilanie i oceń płytę.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Przetestuj każdy klawisz, podświetlenie, Fn i działanie po uśpieniu. body: Nie działają wybrane klawisze, cały rząd lub klawiatura nie jest wykrywana. Sprawdź układ klawiszy, test poza systemem, blokadę Fn, taśmę i historię zalania. Wymień klawiaturę/taśmę zgodnie z numerem części; przy śladach cieczy przerwij zasilanie i oceń płytę. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Przetestuj każdy klawisz, podświetlenie, Fn i działanie po uśpieniu. diagnosis: Sprawdź układ klawiszy, test poza systemem, blokadę Fn, taśmę i historię zalania. repair: Wymień klawiaturę/taśmę zgodnie z numerem części; przy śladach cieczy przerwij zasilanie i oceń płytę. verify: Przetestuj każdy klawisz, podświetlenie, Fn i działanie po uśpieniu. warning: Nie podważaj folii klawiatury i nie używaj płynu bezpośrednio na płycie.','descriptionEn: This lesson isolates keyboard matrix, ribbon-cable, firmware and liquid-damage faults. symptomsEn: This lesson isolates keyboard matrix, ribbon-cable, firmware and liquid-damage faults. stepsEn: Identify the exact model, revision and symptom: Laptop keyboard matrix, ribbon cable and spill diagnosis.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check layout, pre-boot input, Fn lock, ribbon seating and liquid history.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Replace the keyboard or cable using the correct part number; if liquid is present, isolate power and inspect the board.; Repeat the original scenario and check for side effects.; Run the acceptance test: Test every key, backlight, Fn functions and behaviour after sleep. bodyEn: This lesson isolates keyboard matrix, ribbon-cable, firmware and liquid-damage faults. Check layout, pre-boot input, Fn lock, ribbon seating and liquid history. Replace the keyboard or cable using the correct part number; if liquid is present, isolate power and inspect the board. Test every key, backlight, Fn functions and behaviour after sleep. diagnosisEn: Check layout, pre-boot input, Fn lock, ribbon seating and liquid history. repairEn: Replace the keyboard or cable using the correct part number; if liquid is present, isolate power and inspect the board. verifyEn: Test every key, backlight, Fn functions and behaviour after sleep. warningEn: Do not peel keyboard layers or apply liquid cleaner directly to the motherboard.','keyboard,matrix,flex,liquid,EC',''),
('lesson:ADV-143','lesson','Audio / Windows','Audio — kodek, sterownik i tor słuchawkowy','Audio codec, driver and headphone path diagnosis','description: Brak dźwięku, szum, brak mikrofonu lub nieprawidłowe przełączanie wyjść. symptoms: Brak dźwięku, szum, brak mikrofonu lub nieprawidłowe przełączanie wyjść. steps: Zidentyfikuj model, rewizję i dokładny objaw: Audio — kodek, sterownik i tor słuchawkowy.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź wybrane wyjście, głośność aplikacji, prywatność, Menedżer urządzeń i urządzenie zewnętrzne.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Zainstaluj sterownik audio OEM i sprawdź ustawienia; nie zwieraj styków gniazda.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Przetestuj głośniki, słuchawki, mikrofon i audio HDMI/DP jeśli obsługiwane. body: Brak dźwięku, szum, brak mikrofonu lub nieprawidłowe przełączanie wyjść. Sprawdź wybrane wyjście, głośność aplikacji, prywatność, Menedżer urządzeń i urządzenie zewnętrzne. Zainstaluj sterownik audio OEM i sprawdź ustawienia; nie zwieraj styków gniazda. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Przetestuj głośniki, słuchawki, mikrofon i audio HDMI/DP jeśli obsługiwane. diagnosis: Sprawdź wybrane wyjście, głośność aplikacji, prywatność, Menedżer urządzeń i urządzenie zewnętrzne. repair: Zainstaluj sterownik audio OEM i sprawdź ustawienia; nie zwieraj styków gniazda. verify: Przetestuj głośniki, słuchawki, mikrofon i audio HDMI/DP jeśli obsługiwane. warning: Nie testuj głośników przy maksymalnej głośności i nie dotykaj zasilonych padów.','descriptionEn: This lesson diagnoses audio codec, driver, jack detection and Windows output-selection problems. symptomsEn: This lesson diagnoses audio codec, driver, jack detection and Windows output-selection problems. stepsEn: Identify the exact model, revision and symptom: Audio codec, driver and headphone path diagnosis.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check selected output, app volume, privacy permissions, Device Manager and a known-good external device.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Install the OEM audio package and verify settings; do not short jack contacts.; Repeat the original scenario and check for side effects.; Run the acceptance test: Test speakers, headphones, microphone and HDMI/DP audio where supported. bodyEn: This lesson diagnoses audio codec, driver, jack detection and Windows output-selection problems. Check selected output, app volume, privacy permissions, Device Manager and a known-good external device. Install the OEM audio package and verify settings; do not short jack contacts. Test speakers, headphones, microphone and HDMI/DP audio where supported. diagnosisEn: Check selected output, app volume, privacy permissions, Device Manager and a known-good external device. repairEn: Install the OEM audio package and verify settings; do not short jack contacts. verifyEn: Test speakers, headphones, microphone and HDMI/DP audio where supported. warningEn: Avoid testing speakers at maximum volume and do not touch powered test pads.','audio,codec,driver,jack,HDMI',''),
('lesson:ADV-144','lesson','Peryferia / dock','Stacja dokująca — zasilanie, firmware i porty','Docking station power, firmware and port diagnostics','description: Dock ładuje, ale nie wykrywa monitorów, LAN, USB lub odłącza się losowo. symptoms: Dock ładuje, ale nie wykrywa monitorów, LAN, USB lub odłącza się losowo. steps: Zidentyfikuj model, rewizję i dokładny objaw: Stacja dokująca — zasilanie, firmware i porty.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź moc zasilacza docka, upstream port, kabel, standard, firmware i specyfikację hosta.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Testuj minimalny zestaw: zasilacz + host + jeden monitor; aktualizuj firmware z portalu producenta docka.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Dodawaj porty etapami i sprawdź uśpienie/wybudzenie oraz transfer danych. body: Dock ładuje, ale nie wykrywa monitorów, LAN, USB lub odłącza się losowo. Sprawdź moc zasilacza docka, upstream port, kabel, standard, firmware i specyfikację hosta. Testuj minimalny zestaw: zasilacz + host + jeden monitor; aktualizuj firmware z portalu producenta docka. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Dodawaj porty etapami i sprawdź uśpienie/wybudzenie oraz transfer danych. diagnosis: Sprawdź moc zasilacza docka, upstream port, kabel, standard, firmware i specyfikację hosta. repair: Testuj minimalny zestaw: zasilacz + host + jeden monitor; aktualizuj firmware z portalu producenta docka. verify: Dodawaj porty etapami i sprawdź uśpienie/wybudzenie oraz transfer danych. warning: Nie wgrywaj firmware innego modelu i nie używaj zasilacza o niewłaściwej mocy.','descriptionEn: This lesson diagnoses a docking station that charges but fails to provide displays, LAN or USB. symptomsEn: This lesson diagnoses a docking station that charges but fails to provide displays, LAN or USB. stepsEn: Identify the exact model, revision and symptom: Docking station power, firmware and port diagnostics.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check dock power rating, upstream port, cable, supported standard, firmware and host specifications.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Start with power + host + one monitor; update dock firmware only from the manufacturer support page.; Repeat the original scenario and check for side effects.; Run the acceptance test: Add ports one at a time and verify sleep/wake and data transfer. bodyEn: This lesson diagnoses a docking station that charges but fails to provide displays, LAN or USB. Check dock power rating, upstream port, cable, supported standard, firmware and host specifications. Start with power + host + one monitor; update dock firmware only from the manufacturer support page. Add ports one at a time and verify sleep/wake and data transfer. diagnosisEn: Check dock power rating, upstream port, cable, supported standard, firmware and host specifications. repairEn: Start with power + host + one monitor; update dock firmware only from the manufacturer support page. verifyEn: Add ports one at a time and verify sleep/wake and data transfer. warningEn: Never flash firmware for another dock model or use an incorrect power adapter.','dock,USB-C,Thunderbolt,firmware,display',''),
('lesson:ADV-145','lesson','Chłodzenie / serwis','Pasta termiczna i termopady — dobór i docisk','Thermal paste and pad selection and mounting pressure','description: Temperatury są zbyt wysokie po wymianie pasty albo radiator nie przylega prawidłowo. symptoms: Temperatury są zbyt wysokie po wymianie pasty albo radiator nie przylega prawidłowo. steps: Zidentyfikuj model, rewizję i dokładny objaw: Pasta termiczna i termopady — dobór i docisk.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Oceń temperatury, ślady docisku, grubości i rozmieszczenie padów według instrukcji producenta.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Czyść powierzchnie materiałami bezpiecznymi dla elektroniki; stosuj właściwą grubość i kolejność dokręcania.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Porównaj temperatury i hałas w tych samych warunkach; sprawdź brak throttlingu. body: Temperatury są zbyt wysokie po wymianie pasty albo radiator nie przylega prawidłowo. Oceń temperatury, ślady docisku, grubości i rozmieszczenie padów według instrukcji producenta. Czyść powierzchnie materiałami bezpiecznymi dla elektroniki; stosuj właściwą grubość i kolejność dokręcania. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Porównaj temperatury i hałas w tych samych warunkach; sprawdź brak throttlingu. diagnosis: Oceń temperatury, ślady docisku, grubości i rozmieszczenie padów według instrukcji producenta. repair: Czyść powierzchnie materiałami bezpiecznymi dla elektroniki; stosuj właściwą grubość i kolejność dokręcania. verify: Porównaj temperatury i hałas w tych samych warunkach; sprawdź brak throttlingu. warning: Nie zastępuj termopadu pastą i nie dobieraj grubości „na oko”.','descriptionEn: This lesson covers thermal paste and pad selection, thickness, pressure and heatsink contact. symptomsEn: This lesson covers thermal paste and pad selection, thickness, pressure and heatsink contact. stepsEn: Identify the exact model, revision and symptom: Thermal paste and pad selection and mounting pressure.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Review temperatures, contact patterns, pad thickness and placement using manufacturer service information.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Clean with electronics-safe materials; use the specified pad thickness and the documented screw-tightening sequence.; Repeat the original scenario and check for side effects.; Run the acceptance test: Compare temperatures and noise under identical conditions and check for thermal throttling. bodyEn: This lesson covers thermal paste and pad selection, thickness, pressure and heatsink contact. Review temperatures, contact patterns, pad thickness and placement using manufacturer service information. Clean with electronics-safe materials; use the specified pad thickness and the documented screw-tightening sequence. Compare temperatures and noise under identical conditions and check for thermal throttling. diagnosisEn: Review temperatures, contact patterns, pad thickness and placement using manufacturer service information. repairEn: Clean with electronics-safe materials; use the specified pad thickness and the documented screw-tightening sequence. verifyEn: Compare temperatures and noise under identical conditions and check for thermal throttling. warningEn: Never replace a thermal pad with paste or select pad thickness by eye.','thermal paste,pad,heatsink,VRAM,VRM',''),
('lesson:ADV-146','lesson','Zasilanie / PC','Zasilacz ATX — bezpieczna diagnostyka bez otwierania','ATX PSU diagnostics without opening the power supply','description: Komputer wyłącza się, nie startuje lub restartuje przy obciążeniu. symptoms: Komputer wyłącza się, nie startuje lub restartuje przy obciążeniu. steps: Zidentyfikuj model, rewizję i dokładny objaw: Zasilacz ATX — bezpieczna diagnostyka bez otwierania.; Zapisz konfigurację, ostatni znany sprawny stan i komunikaty błędów.; Zabezpiecz dane i ustawienia przed operacją mogącą je zmienić.; Wykonaj test izolacyjny: Sprawdź instalację, przewód, obciążenie i tester PSU zgodnie z instrukcją; porównaj ze znanym sprawnym zasilaczem.; Porównaj wynik z dokumentacją OEM lub standardem i zapisz źródło wartości referencyjnej.; Wybierz działanie po potwierdzeniu przyczyny: Wymień podejrzany zasilacz na zgodny model; nie naprawiaj wnętrza zasilacza w zwykłym warsztacie PC.; Powtórz pierwotny scenariusz i sprawdź, czy nie pojawiły się skutki uboczne.; Wykonaj test odbiorczy: Sprawdź zimny start, stabilność przy kontrolowanym obciążeniu i brak zapachu/nagrzewania. body: Komputer wyłącza się, nie startuje lub restartuje przy obciążeniu. Sprawdź instalację, przewód, obciążenie i tester PSU zgodnie z instrukcją; porównaj ze znanym sprawnym zasilaczem. Wymień podejrzany zasilacz na zgodny model; nie naprawiaj wnętrza zasilacza w zwykłym warsztacie PC. Begin with documentation for the exact model, record the symptom and secure data. Test one variable at a time and record conditions, result and conclusion. Sprawdź zimny start, stabilność przy kontrolowanym obciążeniu i brak zapachu/nagrzewania. diagnosis: Sprawdź instalację, przewód, obciążenie i tester PSU zgodnie z instrukcją; porównaj ze znanym sprawnym zasilaczem. repair: Wymień podejrzany zasilacz na zgodny model; nie naprawiaj wnętrza zasilacza w zwykłym warsztacie PC. verify: Sprawdź zimny start, stabilność przy kontrolowanym obciążeniu i brak zapachu/nagrzewania. warning: Nie otwieraj PSU. Kondensatory mogą zachować niebezpieczny ładunek po odłączeniu.','descriptionEn: This lesson covers external ATX power-supply checks without opening the PSU enclosure. symptomsEn: This lesson covers external ATX power-supply checks without opening the PSU enclosure. stepsEn: Identify the exact model, revision and symptom: ATX PSU diagnostics without opening the power supply.; Record the configuration, last known-good state and error messages.; Secure data and settings before an operation that could modify them.; Run an isolation test: Check mains outlet, cable, system load and an approved PSU tester; compare with a known-good compatible unit.; Compare results with OEM documentation or a standard and record the reference source.; Choose an action only after the cause is confirmed: Replace a suspect PSU with a compatible model; do not repair the PSU internals on a general PC service bench.; Repeat the original scenario and check for side effects.; Run the acceptance test: Check cold starts, stability under a controlled load and absence of abnormal odour or heating. bodyEn: This lesson covers external ATX power-supply checks without opening the PSU enclosure. Check mains outlet, cable, system load and an approved PSU tester; compare with a known-good compatible unit. Replace a suspect PSU with a compatible model; do not repair the PSU internals on a general PC service bench. Check cold starts, stability under a controlled load and absence of abnormal odour or heating. diagnosisEn: Check mains outlet, cable, system load and an approved PSU tester; compare with a known-good compatible unit. repairEn: Replace a suspect PSU with a compatible model; do not repair the PSU internals on a general PC service bench. verifyEn: Check cold starts, stability under a controlled load and absence of abnormal odour or heating. warningEn: Never open an ATX power supply. Capacitors can retain hazardous charge after disconnection.','ATX,PSU,12V,5V,3.3V,protection',''),
('lesson:ADV-147','lesson','Windows / profile','Naprawa profilu użytkownika Windows bez utraty danych','Repairing a Windows user profile without losing data','description: Profil ładuje się tymczasowo, pulpit jest pusty lub aplikacje nie zachowują ustawień. symptoms: System zgłasza profil tymczasowy, błędy logowania lub nie ładuje ustawień użytkownika. steps: Zidentyfikuj model i dokładny scenariusz: Naprawa profilu użytkownika Windows bez utraty danych.; Zapisz objawy, komunikaty, historię zmian i stan danych.; Zabezpiecz dane lub wykonaj kopię, jeżeli operacja może je zmienić.; Sprawdź źródło, logi i dokumentację: Utwórz kopię katalogu użytkownika, sprawdź logi User Profile Service i stan dysku; nie kasuj profilu przed zabezpieczeniem danych.; Wykonaj test izolacyjny, zmieniając jeden czynnik naraz.; Wprowadź wyłącznie potwierdzone działanie: Utwórz nowy profil lub napraw konkretny wpis zgodnie z dokumentacją Microsoft; przenoś dane selektywnie.; Powtórz test pierwotnego objawu i sprawdź skutki uboczne.; Dokumentuj odbiór i ograniczenia: Przetestuj logowanie, uprawnienia, aplikacje i dostępność plików po kilku restartach. body: Profil ładuje się tymczasowo, pulpit jest pusty lub aplikacje nie zachowują ustawień. System zgłasza profil tymczasowy, błędy logowania lub nie ładuje ustawień użytkownika. Utwórz kopię katalogu użytkownika, sprawdź logi User Profile Service i stan dysku; nie kasuj profilu przed zabezpieczeniem danych. Utwórz nowy profil lub napraw konkretny wpis zgodnie z dokumentacją Microsoft; przenoś dane selektywnie. Record the initial state before changes and repeat the original failure scenario afterwards. Distinguish facts, hypotheses and test limitations. Przetestuj logowanie, uprawnienia, aplikacje i dostępność plików po kilku restartach. diagnosis: Utwórz kopię katalogu użytkownika, sprawdź logi User Profile Service i stan dysku; nie kasuj profilu przed zabezpieczeniem danych. repair: Utwórz nowy profil lub napraw konkretny wpis zgodnie z dokumentacją Microsoft; przenoś dane selektywnie. verify: Przetestuj logowanie, uprawnienia, aplikacje i dostępność plików po kilku restartach. warning: Nie edytuj rejestru bez kopii i nie usuwaj katalogu użytkownika w ciemno.','descriptionEn: A temporary profile, missing desktop or settings that fail to persist can indicate a Windows User Profile Service issue. symptomsEn: A temporary profile, missing desktop or settings that fail to persist can indicate a Windows User Profile Service issue. stepsEn: Identify the model and exact scenario: Repairing a Windows user profile without losing data.; Record symptoms, messages, change history and data state.; Secure data or make a backup if the operation can modify it.; Check sources, logs and documentation: Check User Profile Service logs, disk health, recent profile changes and whether the user can sign in with another account.; Run an isolation test, changing one variable at a time.; Apply only the confirmed action: Back up the user folder first. Create a clean profile or repair only the confirmed profile entry using current Microsoft guidance; copy user data selectively.; Repeat the original failure scenario and check side effects.; Document acceptance and limitations: Verify sign-in, permissions, apps, files, profile persistence and several restarts. bodyEn: A temporary profile, missing desktop or settings that fail to persist can indicate a Windows User Profile Service issue. Check User Profile Service logs, disk health, recent profile changes and whether the user can sign in with another account. Back up the user folder first. Create a clean profile or repair only the confirmed profile entry using current Microsoft guidance; copy user data selectively. Verify sign-in, permissions, apps, files, profile persistence and several restarts. Do not delete the original profile or edit the registry without a verified backup. diagnosisEn: Check User Profile Service logs, disk health, recent profile changes and whether the user can sign in with another account. repairEn: Back up the user folder first. Create a clean profile or repair only the confirmed profile entry using current Microsoft guidance; copy user data selectively. verifyEn: Verify sign-in, permissions, apps, files, profile persistence and several restarts. warningEn: Do not delete the original profile or edit the registry without a verified backup.','windows,profile,registry,data',''),
('lesson:ADV-148','lesson','Windows / aktualizacje','Windows Update — diagnoza błędu aktualizacji','Windows Update failure diagnostics','description: Aktualizacja kończy się kodem błędu, cofa zmiany lub długo pozostaje na jednym etapie. symptoms: Aktualizacja kończy się kodem błędu, cofa zmiany lub długo pozostaje na jednym etapie. steps: Zidentyfikuj model i dokładny scenariusz: Windows Update — diagnoza błędu aktualizacji.; Zapisz objawy, komunikaty, historię zmian i stan danych.; Zabezpiecz dane lub wykonaj kopię, jeżeli operacja może je zmienić.; Sprawdź źródło, logi i dokumentację: Zapisz numer KB, kompilację, kod błędu, wolne miejsce i historię instalacji; sprawdź znane problemy Microsoft.; Wykonaj test izolacyjny, zmieniając jeden czynnik naraz.; Wprowadź wyłącznie potwierdzone działanie: Użyj oficjalnego troubleshootera i kolejności DISM/SFC jeśli wskazuje na uszkodzenie obrazu; nie usuwaj losowo katalogów systemowych.; Powtórz test pierwotnego objawu i sprawdź skutki uboczne.; Dokumentuj odbiór i ograniczenia: Potwierdź numer kompilacji, status KB, brak nowych błędów i poprawne działanie usług. body: Aktualizacja kończy się kodem błędu, cofa zmiany lub długo pozostaje na jednym etapie. Aktualizacja kończy się kodem błędu, cofa zmiany lub długo pozostaje na jednym etapie. Zapisz numer KB, kompilację, kod błędu, wolne miejsce i historię instalacji; sprawdź znane problemy Microsoft. Użyj oficjalnego troubleshootera i kolejności DISM/SFC jeśli wskazuje na uszkodzenie obrazu; nie usuwaj losowo katalogów systemowych. Record the initial state before changes and repeat the original failure scenario afterwards. Distinguish facts, hypotheses and test limitations. Potwierdź numer kompilacji, status KB, brak nowych błędów i poprawne działanie usług. diagnosis: Zapisz numer KB, kompilację, kod błędu, wolne miejsce i historię instalacji; sprawdź znane problemy Microsoft. repair: Użyj oficjalnego troubleshootera i kolejności DISM/SFC jeśli wskazuje na uszkodzenie obrazu; nie usuwaj losowo katalogów systemowych. verify: Potwierdź numer kompilacji, status KB, brak nowych błędów i poprawne działanie usług. warning: Nie instaluj pakietu KB dla innej architektury lub wersji systemu.','descriptionEn: A Windows update may fail with a code, roll back changes or remain stuck during servicing. symptomsEn: A Windows update may fail with a code, roll back changes or remain stuck during servicing. stepsEn: Identify the model and exact scenario: Windows Update failure diagnostics.; Record symptoms, messages, change history and data state.; Secure data or make a backup if the operation can modify it.; Check sources, logs and documentation: Record KB, Windows build, error code, free space and update history; check Microsoft release-health notes.; Run an isolation test, changing one variable at a time.; Apply only the confirmed action: Use the official troubleshooter and DISM/SFC where component-store corruption is indicated; do not delete system folders blindly.; Repeat the original failure scenario and check side effects.; Document acceptance and limitations: Confirm the installed build and KB state, review logs and verify core services and restart behaviour. bodyEn: A Windows update may fail with a code, roll back changes or remain stuck during servicing. Record KB, Windows build, error code, free space and update history; check Microsoft release-health notes. Use the official troubleshooter and DISM/SFC where component-store corruption is indicated; do not delete system folders blindly. Confirm the installed build and KB state, review logs and verify core services and restart behaviour. Never install a package for a different Windows version or architecture. diagnosisEn: Record KB, Windows build, error code, free space and update history; check Microsoft release-health notes. repairEn: Use the official troubleshooter and DISM/SFC where component-store corruption is indicated; do not delete system folders blindly. verifyEn: Confirm the installed build and KB state, review logs and verify core services and restart behaviour. warningEn: Never install a package for a different Windows version or architecture.','Windows Update,KB,servicing,DISM',''),
('lesson:ADV-149','lesson','Dane / backup','Kopia zapasowa — test odtwarzania, nie tylko wykonania','Backup validation: test restore, not just job completion','description: Kopia kończy się komunikatem sukcesu, ale nie wiadomo, czy pliki dają się odtworzyć. symptoms: Kopia kończy się komunikatem sukcesu, ale nie wiadomo, czy pliki dają się odtworzyć. steps: Zidentyfikuj model i dokładny scenariusz: Kopia zapasowa — test odtwarzania, nie tylko wykonania.; Zapisz objawy, komunikaty, historię zmian i stan danych.; Zabezpiecz dane lub wykonaj kopię, jeżeli operacja może je zmienić.; Sprawdź źródło, logi i dokumentację: Sprawdź datę, zakres, retencję, szyfrowanie, miejsce docelowe i raport zadania.; Wykonaj test izolacyjny, zmieniając jeden czynnik naraz.; Wprowadź wyłącznie potwierdzone działanie: Wykonaj próbne odtworzenie wybranych plików do oddzielnej lokalizacji i porównaj integralność.; Powtórz test pierwotnego objawu i sprawdź skutki uboczne.; Dokumentuj odbiór i ograniczenia: Potwierdź odczyt, uprawnienia, wersjonowanie i dostęp poza oryginalnym komputerem. body: Kopia kończy się komunikatem sukcesu, ale nie wiadomo, czy pliki dają się odtworzyć. Kopia kończy się komunikatem sukcesu, ale nie wiadomo, czy pliki dają się odtworzyć. Sprawdź datę, zakres, retencję, szyfrowanie, miejsce docelowe i raport zadania. Wykonaj próbne odtworzenie wybranych plików do oddzielnej lokalizacji i porównaj integralność. Record the initial state before changes and repeat the original failure scenario afterwards. Distinguish facts, hypotheses and test limitations. Potwierdź odczyt, uprawnienia, wersjonowanie i dostęp poza oryginalnym komputerem. diagnosis: Sprawdź datę, zakres, retencję, szyfrowanie, miejsce docelowe i raport zadania. repair: Wykonaj próbne odtworzenie wybranych plików do oddzielnej lokalizacji i porównaj integralność. verify: Potwierdź odczyt, uprawnienia, wersjonowanie i dostęp poza oryginalnym komputerem. warning: Nie nadpisuj oryginalnych danych przy teście restore i nie przechowuj kluczy w raporcie.','descriptionEn: A backup job reporting success does not prove that the files can actually be restored. symptomsEn: A backup job reporting success does not prove that the files can actually be restored. stepsEn: Identify the model and exact scenario: Backup validation: test restore, not just job completion.; Record symptoms, messages, change history and data state.; Secure data or make a backup if the operation can modify it.; Check sources, logs and documentation: Check backup date, scope, retention, encryption, target location and job logs.; Run an isolation test, changing one variable at a time.; Apply only the confirmed action: Restore selected test files to a separate location and compare file integrity without overwriting originals.; Repeat the original failure scenario and check side effects.; Document acceptance and limitations: Verify readability, permissions, version history and access from a separate device or location. bodyEn: A backup job reporting success does not prove that the files can actually be restored. Check backup date, scope, retention, encryption, target location and job logs. Restore selected test files to a separate location and compare file integrity without overwriting originals. Verify readability, permissions, version history and access from a separate device or location. Do not test restore over the original data and never put recovery secrets in the service report. diagnosisEn: Check backup date, scope, retention, encryption, target location and job logs. repairEn: Restore selected test files to a separate location and compare file integrity without overwriting originals. verifyEn: Verify readability, permissions, version history and access from a separate device or location. warningEn: Do not test restore over the original data and never put recovery secrets in the service report.','backup,restore,3-2-1,data validation',''),
('lesson:ADV-150','lesson','Organizacja serwisu','Raport serwisowy — diagnoza, części, testy i gwarancja','Service report: diagnosis, parts, tests and warranty','description: Klient potrzebuje jasnego opisu przyczyny, wykonanej naprawy i ograniczeń testów. symptoms: Klient potrzebuje jasnego opisu przyczyny, wykonanej naprawy i ograniczeń testów. steps: Zidentyfikuj model i dokładny scenariusz: Raport serwisowy — diagnoza, części, testy i gwarancja.; Zapisz objawy, komunikaty, historię zmian i stan danych.; Zabezpiecz dane lub wykonaj kopię, jeżeli operacja może je zmienić.; Sprawdź źródło, logi i dokumentację: Rozdziel objaw klienta, ustalenia, hipotezy, potwierdzoną przyczynę i działania wykonane.; Wykonaj test izolacyjny, zmieniając jeden czynnik naraz.; Wprowadź wyłącznie potwierdzone działanie: Wpisz numery części, wersje, źródła, wyniki przed/po i zakres odpowiedzialności; nie zamieszczaj haseł ani kluczy odzyskiwania.; Powtórz test pierwotnego objawu i sprawdź skutki uboczne.; Dokumentuj odbiór i ograniczenia: Ustal test odbiorczy, przekazanie sprzętu, kopię danych i zasady gwarancji usługi. body: Klient potrzebuje jasnego opisu przyczyny, wykonanej naprawy i ograniczeń testów. Klient potrzebuje jasnego opisu przyczyny, wykonanej naprawy i ograniczeń testów. Rozdziel objaw klienta, ustalenia, hipotezy, potwierdzoną przyczynę i działania wykonane. Wpisz numery części, wersje, źródła, wyniki przed/po i zakres odpowiedzialności; nie zamieszczaj haseł ani kluczy odzyskiwania. Record the initial state before changes and repeat the original failure scenario afterwards. Distinguish facts, hypotheses and test limitations. Ustal test odbiorczy, przekazanie sprzętu, kopię danych i zasady gwarancji usługi. diagnosis: Rozdziel objaw klienta, ustalenia, hipotezy, potwierdzoną przyczynę i działania wykonane. repair: Wpisz numery części, wersje, źródła, wyniki przed/po i zakres odpowiedzialności; nie zamieszczaj haseł ani kluczy odzyskiwania. verify: Ustal test odbiorczy, przekazanie sprzętu, kopię danych i zasady gwarancji usługi. warning: Nie obiecuj pełnej sprawności po jednym krótkim teście i nie zapisuj danych poufnych.','descriptionEn: A professional service report should explain the customer symptom, confirmed cause, repair scope and test limitations. symptomsEn: A professional service report should explain the customer symptom, confirmed cause, repair scope and test limitations. stepsEn: Identify the model and exact scenario: Service report: diagnosis, parts, tests and warranty.; Record symptoms, messages, change history and data state.; Secure data or make a backup if the operation can modify it.; Check sources, logs and documentation: Separate the customer report, observed facts, hypotheses, confirmed cause and actions actually performed.; Run an isolation test, changing one variable at a time.; Apply only the confirmed action: Record part numbers, versions, sources and before/after tests; never include passwords or recovery keys.; Repeat the original failure scenario and check side effects.; Document acceptance and limitations: Document acceptance tests, handover, data-backup status and service warranty terms. bodyEn: A professional service report should explain the customer symptom, confirmed cause, repair scope and test limitations. Separate the customer report, observed facts, hypotheses, confirmed cause and actions actually performed. Record part numbers, versions, sources and before/after tests; never include passwords or recovery keys. Document acceptance tests, handover, data-backup status and service warranty terms. Do not promise total reliability based on one short test or record confidential customer data. diagnosisEn: Separate the customer report, observed facts, hypotheses, confirmed cause and actions actually performed. repairEn: Record part numbers, versions, sources and before/after tests; never include passwords or recovery keys. verifyEn: Document acceptance tests, handover, data-backup status and service warranty terms. warningEn: Do not promise total reliability based on one short test or record confidential customer data.','service report,diagnosis,QA,customer,documentation',''),
('lesson:PRO31-001','lesson','Płyta główna / VRM','Diagnostyka sekcji zasilania CPU (VRM)','CPU VRM power-stage diagnostics','description: Analiza wejścia EPS, kontrolera PWM, faz zasilania, MOSFET-ów i cewek na podstawie schematu konkretnej płyty. symptoms: PC wyłącza się pod obciążeniem, CPU nie osiąga deklarowanych zegarów lub płyta nie przechodzi POST. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: PC wyłącza się pod obciążeniem, CPU nie osiąga deklarowanych zegarów lub płyta nie przechodzi POST. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Naprawa ma wynikać z pomiarów kontrolera, przebiegu zasilania i oględzin elementów; wymieniaj tylko potwierdzony uszkodzony element. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Analiza wejścia EPS, kontrolera PWM, faz zasilania, MOSFET-ów i cewek na podstawie schematu konkretnej płyty. Objawy i kontekst: PC wyłącza się pod obciążeniem, CPU nie osiąga deklarowanych zegarów lub płyta nie przechodzi POST. Tok diagnostyczny: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. Zasada naprawy: Naprawa ma wynikać z pomiarów kontrolera, przebiegu zasilania i oględzin elementów; wymieniaj tylko potwierdzony uszkodzony element. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. repair: Naprawa ma wynikać z pomiarów kontrolera, przebiegu zasilania i oględzin elementów; wymieniaj tylko potwierdzony uszkodzony element. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie wykonuj pomiarów po stronie sieciowej PSU. Pomiary na pracującej płycie wymagają kwalifikacji, sond zabezpieczonych i dokumentacji. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: CPU VRM power-stage diagnostics SCOPE Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Diagnostyka,sekcji,zasilania,CPU,VRM,Płyta,główna,VRM',''),
('lesson:PRO31-002','lesson','GPU / grafika','Diagnostyka braku obrazu z dedykowanej karty GPU','Dedicated GPU no-display diagnostics','description: Oddziel usterkę karty, slotu PCIe, przewodu obrazu, monitora, firmware i sterownika. symptoms: Wentylatory ruszają, ale monitor nie wykrywa sygnału; system może uruchamiać się w tle. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Wentylatory ruszają, ale monitor nie wykrywa sygnału; system może uruchamiać się w tle. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Dopiero po izolacji przyczyny wykonaj kontrolę złącza, zasilania PCIe i test karty w zgodnym, sprawnym zestawie. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Oddziel usterkę karty, slotu PCIe, przewodu obrazu, monitora, firmware i sterownika. Objawy i kontekst: Wentylatory ruszają, ale monitor nie wykrywa sygnału; system może uruchamiać się w tle. Tok diagnostyczny: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. Zasada naprawy: Dopiero po izolacji przyczyny wykonaj kontrolę złącza, zasilania PCIe i test karty w zgodnym, sprawnym zestawie. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. repair: Dopiero po izolacji przyczyny wykonaj kontrolę złącza, zasilania PCIe i test karty w zgodnym, sprawnym zestawie. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie wkładaj i nie wyjmuj GPU przy zasilonym komputerze; nie dotykaj styków ani nie zwieraj pinów slotu. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: Dedicated GPU no-display diagnostics SCOPE Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Diagnostyka,braku,obrazu,z,dedykowanej,karty,GPU,GPU,grafika',''),
('lesson:PRO31-003','lesson','GPU / grafika','Artefakty obrazu i niestabilność pamięci VRAM','Display artifacts and VRAM instability','description: Rozpoznawanie artefaktów zależnych od temperatury, obciążenia, sterownika i połączenia wyświetlacza. symptoms: Kolorowe bloki, migotanie, błędy tekstur, reset sterownika lub czarny ekran. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Kolorowe bloki, migotanie, błędy tekstur, reset sterownika lub czarny ekran. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Przyczynę potwierdź powtarzalnym testem; sterownik, przewód lub monitor wyklucz przed podejrzeniem VRAM. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Rozpoznawanie artefaktów zależnych od temperatury, obciążenia, sterownika i połączenia wyświetlacza. Objawy i kontekst: Kolorowe bloki, migotanie, błędy tekstur, reset sterownika lub czarny ekran. Tok diagnostyczny: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. Zasada naprawy: Przyczynę potwierdź powtarzalnym testem; sterownik, przewód lub monitor wyklucz przed podejrzeniem VRAM. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. repair: Przyczynę potwierdź powtarzalnym testem; sterownik, przewód lub monitor wyklucz przed podejrzeniem VRAM. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie używaj długich testów obciążeniowych przy artefaktach, przegrzewaniu lub zapachu spalenizny. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Identify artifacts correlated with temperature, load, driver and display connection. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: Display artifacts and VRAM instability SCOPE Identify artifacts correlated with temperature, load, driver and display connection. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Identify artifacts correlated with temperature, load, driver and display connection. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Identify artifacts correlated with temperature, load, driver and display connection. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Identify artifacts correlated with temperature, load, driver and display connection. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Identify artifacts correlated with temperature, load, driver and display connection. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Identify artifacts correlated with temperature, load, driver and display connection. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Identify artifacts correlated with temperature, load, driver and display connection. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Artefakty,obrazu,i,niestabilność,pamięci,VRAM,GPU,grafika',''),
('lesson:PRO31-004','lesson','BIOS / firmware','Odtwarzanie BIOS z funkcji Flashback','BIOS recovery using Flashback','description: Przygotowanie zgodnego obrazu firmware, nośnika USB, nazwy pliku i sekwencji odzyskiwania według OEM. symptoms: Płyta nie przechodzi POST po przerwanym update albo firmware nie uruchamia konfiguracji. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Płyta nie przechodzi POST po przerwanym update albo firmware nie uruchamia konfiguracji. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Użyj wyłącznie obrazu z oficjalnej strony dla dokładnej rewizji. Zachowaj stabilne zasilanie i nie przerywaj procesu. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Przygotowanie zgodnego obrazu firmware, nośnika USB, nazwy pliku i sekwencji odzyskiwania według OEM. Objawy i kontekst: Płyta nie przechodzi POST po przerwanym update albo firmware nie uruchamia konfiguracji. Tok diagnostyczny: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. Zasada naprawy: Użyj wyłącznie obrazu z oficjalnej strony dla dokładnej rewizji. Zachowaj stabilne zasilanie i nie przerywaj procesu. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. repair: Użyj wyłącznie obrazu z oficjalnej strony dla dokładnej rewizji. Zachowaj stabilne zasilanie i nie przerywaj procesu. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie flashuj obrazu z podobnego modelu. Nie odłączaj zasilania, gdy dioda wskazuje trwający zapis. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: BIOS recovery using Flashback SCOPE Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Odtwarzanie,BIOS,z,funkcji,Flashback,BIOS,firmware',''),
('lesson:PRO31-005','lesson','BIOS / UEFI','Analiza ustawień UEFI i kolejności bootowania','UEFI settings and boot-order analysis','description: Rozróżnianie UEFI/Legacy, GPT/MBR, Secure Boot, CSM, trybu kontrolera i wpisów boot managera. symptoms: Komunikat no bootable device, zniknięcie wpisu Windows Boot Manager lub pętla firmware. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Komunikat no bootable device, zniknięcie wpisu Windows Boot Manager lub pętla firmware. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Przywracaj ustawienia pojedynczo i zgodnie z pierwotnym sposobem instalacji systemu. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Rozróżnianie UEFI/Legacy, GPT/MBR, Secure Boot, CSM, trybu kontrolera i wpisów boot managera. Objawy i kontekst: Komunikat no bootable device, zniknięcie wpisu Windows Boot Manager lub pętla firmware. Tok diagnostyczny: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. Zasada naprawy: Przywracaj ustawienia pojedynczo i zgodnie z pierwotnym sposobem instalacji systemu. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. repair: Przywracaj ustawienia pojedynczo i zgodnie z pierwotnym sposobem instalacji systemu. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie przełączaj AHCI/RAID/VMD ani Secure Boot bez oceny wpływu na rozruch i klucze odzyskiwania. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: UEFI settings and boot-order analysis SCOPE Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Analiza,ustawień,UEFI,i,kolejności,bootowania,BIOS,UEFI',''),
('lesson:PRO31-006','lesson','Firmware / bezpieczeństwo','Diagnostyka TPM 2.0 i Secure Boot','TPM 2.0 and Secure Boot diagnostics','description: Weryfikacja stanu TPM, trybu Secure Boot, kluczy platformy i wymagań systemu. symptoms: Windows zgłasza brak TPM, stan Secure Boot jest niepoprawny albo aplikacja nie spełnia wymagań. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Windows zgłasza brak TPM, stan Secure Boot jest niepoprawny albo aplikacja nie spełnia wymagań. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Ustawienia zmieniaj po kopii kluczy odzyskiwania BitLocker i sprawdzeniu wymagań producenta. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Weryfikacja stanu TPM, trybu Secure Boot, kluczy platformy i wymagań systemu. Objawy i kontekst: Windows zgłasza brak TPM, stan Secure Boot jest niepoprawny albo aplikacja nie spełnia wymagań. Tok diagnostyczny: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. Zasada naprawy: Ustawienia zmieniaj po kopii kluczy odzyskiwania BitLocker i sprawdzeniu wymagań producenta. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. repair: Ustawienia zmieniaj po kopii kluczy odzyskiwania BitLocker i sprawdzeniu wymagań producenta. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie czyść TPM na urządzeniu użytkownika bez kopii kluczy i zgody — może to uniemożliwić dostęp do danych. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: TPM 2.0 and Secure Boot diagnostics SCOPE Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Diagnostyka,TPM,2,0,i,Secure,Boot,Firmware,bezpieczeństwo',''),
('lesson:PRO31-007','lesson','Laptop / EC','Diagnostyka kontrolera EC/KBC','Embedded Controller (EC/KBC) diagnostics','description: Rozpoznawanie objawów związanych z kontrolerem klawiatury, przyciskiem Power, ładowaniem i sekwencją startową. symptoms: Brak reakcji przycisku, nietypowe diody, brak ładowania lub nieregularny start. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Brak reakcji przycisku, nietypowe diody, brak ładowania lub nieregularny start. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Weryfikuj firmware EC i procedurę producenta; programowanie układu powierz technikowi z właściwym sprzętem. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Rozpoznawanie objawów związanych z kontrolerem klawiatury, przyciskiem Power, ładowaniem i sekwencją startową. Objawy i kontekst: Brak reakcji przycisku, nietypowe diody, brak ładowania lub nieregularny start. Tok diagnostyczny: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. Zasada naprawy: Weryfikuj firmware EC i procedurę producenta; programowanie układu powierz technikowi z właściwym sprzętem. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. repair: Weryfikuj firmware EC i procedurę producenta; programowanie układu powierz technikowi z właściwym sprzętem. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie zwieraj pinów EC ani nie wgrywaj wsadu z innej rewizji płyty. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: Embedded Controller (EC/KBC) diagnostics SCOPE Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Diagnostyka,kontrolera,EC,KBC,Laptop,EC',''),
('lesson:PRO31-008','lesson','Bateria / zasilanie','Ocena kondycji baterii laptopa','Laptop battery health assessment','description: Analiza pojemności projektowej i pełnego ładowania, cykli, napięcia, temperatury i komunikacji BMS. symptoms: Krótki czas pracy, nagłe wyłączenie, brak ładowania lub komunikat o niewykrytej baterii. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Krótki czas pracy, nagłe wyłączenie, brak ładowania lub komunikat o niewykrytej baterii. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Wymieniaj baterię tylko na zgodny, certyfikowany moduł; po wymianie wykonaj kalibrację, jeśli zaleca ją producent. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Analiza pojemności projektowej i pełnego ładowania, cykli, napięcia, temperatury i komunikacji BMS. Objawy i kontekst: Krótki czas pracy, nagłe wyłączenie, brak ładowania lub komunikat o niewykrytej baterii. Tok diagnostyczny: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. Zasada naprawy: Wymieniaj baterię tylko na zgodny, certyfikowany moduł; po wymianie wykonaj kalibrację, jeśli zaleca ją producent. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. repair: Wymieniaj baterię tylko na zgodny, certyfikowany moduł; po wymianie wykonaj kalibrację, jeśli zaleca ją producent. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Spuchniętej, przebitej lub przegrzewającej się baterii nie naciskaj, nie przebijaj ani nie ładuj. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: Laptop battery health assessment SCOPE Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Ocena,kondycji,baterii,laptopa,Bateria,zasilanie',''),
('lesson:PRO31-009','lesson','USB-C / PD','Analiza negocjacji USB-C Power Delivery','USB-C Power Delivery negotiation analysis','description: Rozpoznawanie ról źródła i odbiornika, komunikatów CC, profili PDO i ograniczeń kabla/adaptera. symptoms: Urządzenie ładuje się wolno, przerywa ładowanie lub działa tylko z wybranym adapterem. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Urządzenie ładuje się wolno, przerywa ładowanie lub działa tylko z wybranym adapterem. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Porównaj adapter, kabel e-marked, port i odbiornik; użyj miernika PD zgodnego ze specyfikacją. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Wymień wyłącznie element potwierdzony testem; port i kontroler analizuj na schemacie dokładnej rewizji. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Rozpoznawanie ról źródła i odbiornika, komunikatów CC, profili PDO i ograniczeń kabla/adaptera. Objawy i kontekst: Urządzenie ładuje się wolno, przerywa ładowanie lub działa tylko z wybranym adapterem. Tok diagnostyczny: Porównaj adapter, kabel e-marked, port i odbiornik; użyj miernika PD zgodnego ze specyfikacją. Zasada naprawy: Wymień wyłącznie element potwierdzony testem; port i kontroler analizuj na schemacie dokładnej rewizji. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Porównaj adapter, kabel e-marked, port i odbiornik; użyj miernika PD zgodnego ze specyfikacją. repair: Wymień wyłącznie element potwierdzony testem; port i kontroler analizuj na schemacie dokładnej rewizji. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie podawaj napięcia na nieznane piny ani nie używaj przypadkowych adapterów laboratoryjnych. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: USB-C Power Delivery negotiation analysis SCOPE Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Analiza,negocjacji,USB-C,Power,Delivery,USB-C,PD',''),
('lesson:PRO31-010','lesson','USB / Thunderbolt','Diagnostyka Thunderbolt i stacji dokującej','Thunderbolt and docking-station diagnostics','description: Izolowanie problemów firmware, kabla, portu, autoryzacji, zasilania i zgodności urządzenia. symptoms: Dock nie wykrywa monitorów, LAN, USB lub ładowania mimo podłączenia. steps: Przyjmij urządzenie: zapisz dokładny model, numer rewizji, wersję BIOS/UEFI i konfigurację. Opisz zgłoszenie klienta własnymi słowami.; Zapisz objaw i warunki: Dock nie wykrywa monitorów, LAN, USB lub ładowania mimo podłączenia. Nie zmieniaj kilku ustawień jednocześnie.; Zabezpiecz dane i ustal zgodę na testy. Przy podejrzeniu awarii nośnika najpierw zaplanuj obraz lub kopię, nie benchmark.; Przygotuj stanowisko ESD, właściwe narzędzia i dokumentację producenta dokładnego modelu. Obejrzyj złącza, śruby i ślady uszkodzeń.; Zweryfikuj hipotezy: Sprawdź certyfikację i oznaczenia kabla, firmware docka, listę zgodności oraz zdarzenia systemowe. Zapisz wynik każdego testu wraz z jednostką, warunkami i źródłem wartości odniesienia.; Wykonaj test izolacyjny: porównaj znany sprawny przewód/port/urządzenie albo minimalną konfigurację. Zmieniaj tylko jeden czynnik.; Sprawdź logi, kody i wersje. Rozróżnij zdarzenie źródłowe od skutku oraz błąd powtarzalny od pojedynczego incydentu.; Dobierz rozwiązanie: Testuj osobno monitor, zasilanie, USB i LAN; aktualizuj firmware wyłącznie według OEM. Nie wymieniaj części na podstawie samego objawu.; Wykonaj naprawę zgodnie z instrukcją serwisową i kolejnością producenta. Udokumentuj użyte części, wersje i wykonane czynności.; Powtórz pierwotny scenariusz, wykonaj test końcowy, sprawdź inne funkcje, zamontuj obudowę i przygotuj raport dla klienta. body: Izolowanie problemów firmware, kabla, portu, autoryzacji, zasilania i zgodności urządzenia. Objawy i kontekst: Dock nie wykrywa monitorów, LAN, USB lub ładowania mimo podłączenia. Tok diagnostyczny: Sprawdź certyfikację i oznaczenia kabla, firmware docka, listę zgodności oraz zdarzenia systemowe. Zasada naprawy: Testuj osobno monitor, zasilanie, USB i LAN; aktualizuj firmware wyłącznie według OEM. Dokumentuj każdy etap. Test ma potwierdzać jedną hipotezę; wynik negatywny również zapisuj. Przed wymianą części sprawdź zgodność numeru części i procedurę producenta. diagnosis: Sprawdź certyfikację i oznaczenia kabla, firmware docka, listę zgodności oraz zdarzenia systemowe. repair: Testuj osobno monitor, zasilanie, USB i LAN; aktualizuj firmware wyłącznie według OEM. verify: Odtwórz pierwotny objaw w tych samych warunkach. Wykonaj testy funkcji powiązanych z naprawą, monitoruj stabilność i temperatury w granicach specyfikacji. Zapisz konfigurację i wynik PASS/FAIL. warning: Nie wymuszaj niezgodnego trybu zasilania; aktualizacja docka może przerwać pracę wszystkich portów. step: Najpierw zabezpiecz dane, określ zgodę na testy i potwierdź dokładny model/rewizję.','descriptionEn: Isolate firmware, cable, port, authorization, power and device-compatibility issues. symptomsEn: Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. stepsEn: Confirm the exact model, part number, board revision and firmware version.; Record the reported symptom and the conditions required to reproduce it.; Protect customer data and obtain authorization before intrusive work.; Prepare an ESD-safe workspace and the correct OEM service documentation.; Inspect connectors, cables and visible damage with power safely isolated.; Run one controlled test at a time and record units, conditions and results.; Compare observations with the specification for the exact model and revision.; Select a repair only after the root cause is supported by repeatable evidence.; Perform the approved repair and document parts, firmware and adjustments.; Repeat the original scenario, test related functions and issue a PASS/FAIL report. bodyEn: Thunderbolt and docking-station diagnostics SCOPE Isolate firmware, cable, port, authorization, power and device-compatibility issues. SYMPTOMS AND CONTEXT Symptoms must be reproduced and recorded under the same conditions. Note the exact model, revision, workload, connected accessories, time to failure and any recent hardware or software change. DIAGNOSTIC METHOD Confirm the exact model and board revision. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. REPAIR AND ACCEPTANCE Repair only after a repeatable test confirms the root cause. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. SAFETY Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Do not guess pinouts, firmware files or electrical limits. diagnosisEn: Confirm the exact model and board revision. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Isolate one hypothesis at a time, compare findings with the correct OEM documentation and record measurements with units and test conditions. repairEn: Repair only after a repeatable test confirms the root cause. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Use parts and procedures verified for the exact model and revision; document the work and run an acceptance test. verifyEn: Reproduce the original symptom under the same conditions. Test related functions, monitor stability and temperatures within specifications. Record configuration and PASS/FAIL results. warningEn: Stop work for smoke, burning smell, liquid damage, a swollen or hot battery, exposed mains voltage or an unidentified short. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Do not guess pinouts, firmware files or electrical limits. stepEn: Confirm the exact model, part number, board revision and firmware version.','Diagnostyka,Thunderbolt,i,stacji,dokującej,USB,Thunderbolt','');
